int nlmsg_dump(struct sock *sk)
{
    struct sk_buff *skb;
    int err = 0;

    mutex_lock(&sk->sk_mutex);
    if (sk->sk_callback_running) {
        mutex_unlock(&sk->sk_mutex);
        return -EBUSY;
    }

    if (sk->sk_rcvbuf * 3 / 4 > sk->sk_wmem_queued) {
        skb = alloc_skb(sk->sk_rcvbuf, GFP_KERNEL);
        if (!skb) {
            err = -ENOMEM;
            goto out;
        }
    } else {
        skb = alloc_skb(sk->sk_rcvbuf / 2, GFP_KERNEL);
        if (!skb) {
            err = -ENOMEM;
            goto out;
        }
    }

    if (sk->sk_data_ready(sk, skb)) {
        err = -EFAULT;
        kfree_skb(skb);
        goto out;
    }

    if (sk->sk_dump(sk, skb)) {
        if (sk_filter(sk, skb)) {
            netlink_unicast(sk, skb, sk->sk_peer_pid);
        } else {
            kfree_skb(skb);
        }
    } else {
        err = -EIO;
        kfree_skb(skb);
    }

out:
    mutex_unlock(&sk->sk_mutex);
    return err;
}

int netlink_dump(struct sock *sk)
{
    struct sk_buff *skb;
    int err = 0;

    mutex_lock(&dump_mutex);

    if (dump_callback_running) {
        mutex_unlock(&dump_mutex);
        return -EBUSY;
    }

    if (skb_queue_len(&sk->sk_receive_queue) >= sk->sk_rcvbuf) {
        mutex_unlock(&dump_mutex);
        return -ENOBUFS;
    }

    skb = alloc_skb(sk->sk_rcvbuf, GFP_KERNEL);
    if (!skb) {
        mutex_unlock(&dump_mutex);
        return -ENOMEM;
    }

    dump_callback_running = true;

    err = sk->sk_prot->dump(skb, sk);
    if (err < 0) {
        kfree_skb(skb);
        dump_callback_running = false;
        mutex_unlock(&dump_mutex);
        return err;
    }

    if (apply_filters(skb)) {
        netlink_send(skb, sk);
    } else {
        kfree_skb(skb);
    }

    dump_callback_running = false;
    mutex_unlock(&dump_mutex);

    return 0;
}
